import {recentActivity} from '../services/recentActivity.js';
import {reportContent,reviewContent} from '../services/moderation.js';
import {documentVisibility,requireDocumentView} from '../services/documentAccess.js';
import {localWeather} from '../services/weather.js';
import {personalActivity} from '../services/personalActivity.js';
import {levyRouter} from './levies.js';
import { Router } from 'express';
import crypto from 'node:crypto';
import bcrypt from 'bcryptjs';
import { z } from 'zod';
import { getPool, sql } from '../config/db.js';
import { requireAuth } from '../middleware/auth.js';
import { asyncHandler, AppError } from '../utils/errors.js';
import { hasPermission, requireCommunityMember, requirePermission } from '../services/permissions.js';
import { audit } from '../services/audit.js';
import { deleteObject } from '../services/storage.js';
import { getRedis } from '../config/redis.js';
import { env } from '../config/env.js';

export const advancedRouter=Router();
advancedRouter.use(requireAuth);
advancedRouter.post('/me/weather',asyncHandler(async(req,res)=>{res.set('Cache-Control','no-store');res.json(await localWeather(req.body));}));
const member=async(uid:string,cid:string)=>requireCommunityMember(uid,cid);
const documentCategories=['Constitution','Policies','Meeting minutes','Financial reports','Forms','Newsletters','Community rules','Emergency procedures','Archives','Other'] as const;
export {requireDocumentView} from '../services/documentAccess.js';

advancedRouter.get('/me/support-tickets',asyncHandler(async(req,res)=>{const p=await getPool();const r=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query('SELECT Id,Category,Subject,Message,Status,CreatedAt,UpdatedAt FROM SupportTickets WHERE UserId=@u ORDER BY CreatedAt DESC');res.json(r.recordset);}));
advancedRouter.post('/me/support-tickets',asyncHandler(async(req,res)=>{const d=z.object({category:z.enum(['GENERAL','ACCOUNT','TECHNICAL','SAFETY','PAYMENTS']),subject:z.string().trim().min(3).max(200),message:z.string().trim().min(10).max(4000)}).parse(req.body);const p=await getPool();const r=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('category',sql.NVarChar(40),d.category).input('subject',sql.NVarChar(200),d.subject).input('message',sql.NVarChar(4000),d.message).query('INSERT INTO SupportTickets(UserId,Category,Subject,Message) OUTPUT INSERTED.Id,INSERTED.Category,INSERTED.Subject,INSERTED.Message,INSERTED.Status,INSERTED.CreatedAt,INSERTED.UpdatedAt VALUES(@u,@category,@subject,@message)');res.status(201).json(r.recordset[0]);}));

// Governance: proposal -> discussion -> amendments -> vote -> decision -> action -> progress
advancedRouter.get('/communities/:communityId/governance/proposals',asyncHandler(async(req,res)=>{await member(req.user!.id,req.params.communityId);const p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT gp.*,u.FirstName,u.LastName,(SELECT COUNT(*) FROM ProposalDiscussions d WHERE d.ProposalId=gp.Id) DiscussionCount,(SELECT COUNT(*) FROM ProposalAmendments a WHERE a.ProposalId=gp.Id) AmendmentCount FROM GovernanceProposals gp JOIN Users u ON u.Id=gp.CreatedBy WHERE gp.CommunityId=@c ORDER BY gp.CreatedAt DESC`);res.json(r.recordset);}));
advancedRouter.post('/communities/:communityId/governance/proposals',asyncHandler(async(req,res)=>{await member(req.user!.id,req.params.communityId);const d=z.object({title:z.string().min(3).max(250),summary:z.string().max(2000).optional(),body:z.string().min(5),discussionClosesAt:z.coerce.date().optional()}).parse(req.body);const p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('t',sql.NVarChar(250),d.title).input('s',sql.NVarChar(2000),d.summary??null).input('b',sql.NVarChar(sql.MAX),d.body).input('dc',sql.DateTime2,d.discussionClosesAt??null).query(`INSERT INTO GovernanceProposals(CommunityId,CreatedBy,Title,Summary,Body,DiscussionClosesAt) OUTPUT INSERTED.* VALUES(@c,@u,@t,@s,@b,@dc)`);await audit(req.params.communityId,req.user!.id,'PROPOSAL_CREATED','GovernanceProposal',r.recordset[0].Id);res.status(201).json(r.recordset[0]);}));
advancedRouter.get('/governance/proposals/:proposalId',asyncHandler(async(req,res)=>{const p=await getPool();const q=await p.request().input('id',sql.UniqueIdentifier,req.params.proposalId).query(`SELECT * FROM GovernanceProposals WHERE Id=@id`);const proposal=q.recordset[0];if(!proposal)throw new AppError(404,'Proposal not found');await member(req.user!.id,proposal.CommunityId);const discussions=await p.request().input('id',sql.UniqueIdentifier,req.params.proposalId).query(`SELECT d.*,u.FirstName,u.LastName FROM ProposalDiscussions d JOIN Users u ON u.Id=d.UserId WHERE d.ProposalId=@id ORDER BY d.CreatedAt`);const amendments=await p.request().input('id',sql.UniqueIdentifier,req.params.proposalId).query(`SELECT a.*,u.FirstName,u.LastName FROM ProposalAmendments a JOIN Users u ON u.Id=a.ProposedBy WHERE a.ProposalId=@id ORDER BY a.CreatedAt`);res.json({proposal,discussions:discussions.recordset,amendments:amendments.recordset});}));
advancedRouter.post('/governance/proposals/:proposalId/discussion',asyncHandler(async(req,res)=>{const d=z.object({body:z.string().min(1).max(4000),parentId:z.string().uuid().optional()}).parse(req.body);const p=await getPool();const q=await p.request().input('id',sql.UniqueIdentifier,req.params.proposalId).query(`SELECT CommunityId,Status FROM GovernanceProposals WHERE Id=@id`);const x=q.recordset[0];if(!x)throw new AppError(404,'Proposal not found');await member(req.user!.id,x.CommunityId);if(!['DISCUSSION','AMENDMENT'].includes(x.Status))throw new AppError(409,'Discussion is closed');const r=await p.request().input('p',sql.UniqueIdentifier,req.params.proposalId).input('u',sql.UniqueIdentifier,req.user!.id).input('b',sql.NVarChar(4000),d.body).input('parent',sql.UniqueIdentifier,d.parentId??null).query(`INSERT INTO ProposalDiscussions(ProposalId,UserId,Body,ParentId) OUTPUT INSERTED.* VALUES(@p,@u,@b,@parent)`);res.status(201).json(r.recordset[0]);}));
advancedRouter.post('/governance/proposals/:proposalId/amendments',asyncHandler(async(req,res)=>{const d=z.object({title:z.string().min(2).max(250),body:z.string().min(2)}).parse(req.body);const p=await getPool();const q=await p.request().input('id',sql.UniqueIdentifier,req.params.proposalId).query(`SELECT CommunityId,Status FROM GovernanceProposals WHERE Id=@id`);const x=q.recordset[0];if(!x)throw new AppError(404,'Proposal not found');await member(req.user!.id,x.CommunityId);if(!['DISCUSSION','AMENDMENT'].includes(x.Status))throw new AppError(409,'Amendments are closed');const r=await p.request().input('p',sql.UniqueIdentifier,req.params.proposalId).input('u',sql.UniqueIdentifier,req.user!.id).input('t',sql.NVarChar(250),d.title).input('b',sql.NVarChar(sql.MAX),d.body).query(`INSERT INTO ProposalAmendments(ProposalId,ProposedBy,Title,Body) OUTPUT INSERTED.* VALUES(@p,@u,@t,@b)`);res.status(201).json(r.recordset[0]);}));
advancedRouter.patch('/governance/proposals/:proposalId/status',asyncHandler(async(req,res)=>{const d=z.object({status:z.enum(['DISCUSSION','AMENDMENT','VOTING','DECIDED','ACTION','CLOSED']),decisionText:z.string().optional()}).parse(req.body);const p=await getPool();const q=await p.request().input('id',sql.UniqueIdentifier,req.params.proposalId).query(`SELECT CommunityId,Title FROM GovernanceProposals WHERE Id=@id`);const x=q.recordset[0];if(!x)throw new AppError(404,'Proposal not found');await requirePermission(req.user!.id,x.CommunityId,'GOVERNANCE_MANAGE');await p.request().input('id',sql.UniqueIdentifier,req.params.proposalId).input('s',sql.NVarChar(30),d.status).input('dt',sql.NVarChar(sql.MAX),d.decisionText??null).query(`UPDATE GovernanceProposals SET Status=@s,DecisionText=COALESCE(@dt,DecisionText),DecidedAt=CASE WHEN @s='DECIDED' THEN SYSUTCDATETIME() ELSE DecidedAt END,UpdatedAt=SYSUTCDATETIME() WHERE Id=@id`);if(d.status==='DECIDED'&&d.decisionText){await p.request().input('c',sql.UniqueIdentifier,x.CommunityId).input('pid',sql.UniqueIdentifier,req.params.proposalId).input('t',sql.NVarChar(250),x.Title).input('d',sql.NVarChar(sql.MAX),d.decisionText).input('u',sql.UniqueIdentifier,req.user!.id).query(`IF NOT EXISTS(SELECT 1 FROM DecisionRegister WHERE ProposalId=@pid) INSERT INTO DecisionRegister(CommunityId,ProposalId,Title,DecisionText,SearchText,RecordedBy) VALUES(@c,@pid,@t,@d,@t+' '+@d,@u)`);}res.json({success:true});}));
advancedRouter.get('/communities/:communityId/decisions',asyncHandler(async(req,res)=>{await member(req.user!.id,req.params.communityId);const q=String(req.query.q??'').trim();const p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('q',sql.NVarChar(500),`%${q}%`).query(`SELECT d.*,(SELECT COUNT(*) FROM GovernanceActions a WHERE a.DecisionId=d.Id OR a.ProposalId=d.ProposalId) ActionCount FROM DecisionRegister d WHERE d.CommunityId=@c AND (@q='%%' OR d.Title LIKE @q OR d.DecisionText LIKE @q OR d.Tags LIKE @q OR d.SearchText LIKE @q) ORDER BY d.DecisionDate DESC`);res.json(r.recordset);}));
advancedRouter.post('/communities/:communityId/governance/actions',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'GOVERNANCE_MANAGE');const d=z.object({proposalId:z.string().uuid().optional(),decisionId:z.string().uuid().optional(),title:z.string().min(2).max(250),description:z.string().optional(),assignedTo:z.string().uuid().optional(),dueAt:z.coerce.date().optional()}).parse(req.body);const p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('p',sql.UniqueIdentifier,d.proposalId??null).input('di',sql.UniqueIdentifier,d.decisionId??null).input('t',sql.NVarChar(250),d.title).input('d',sql.NVarChar(sql.MAX),d.description??null).input('a',sql.UniqueIdentifier,d.assignedTo??null).input('due',sql.DateTime2,d.dueAt??null).input('u',sql.UniqueIdentifier,req.user!.id).query(`INSERT INTO GovernanceActions(CommunityId,ProposalId,DecisionId,Title,Description,AssignedTo,DueAt,CreatedBy) OUTPUT INSERTED.* VALUES(@c,@p,@di,@t,@d,@a,@due,@u)`);res.status(201).json(r.recordset[0]);}));
advancedRouter.patch('/governance/actions/:actionId',asyncHandler(async(req,res)=>{const d=z.object({status:z.enum(['OPEN','IN_PROGRESS','BLOCKED','DONE']),progressPercent:z.number().int().min(0).max(100)}).parse(req.body);const p=await getPool();const q=await p.request().input('id',sql.UniqueIdentifier,req.params.actionId).query(`SELECT CommunityId FROM GovernanceActions WHERE Id=@id`);if(!q.recordset[0])throw new AppError(404,'Action not found');await requirePermission(req.user!.id,q.recordset[0].CommunityId,'GOVERNANCE_MANAGE');await p.request().input('id',sql.UniqueIdentifier,req.params.actionId).input('s',sql.NVarChar(30),d.status).input('pr',sql.Int,d.progressPercent).query(`UPDATE GovernanceActions SET Status=@s,ProgressPercent=@pr,UpdatedAt=SYSUTCDATETIME() WHERE Id=@id`);res.json({success:true});}));

// Formal voting. Eligibility is snapshotted. Anonymous ballots record a receipt separately from the ballot vote.
advancedRouter.get('/communities/:communityId/formal-ballots',asyncHandler(async(req,res)=>{await member(req.user!.id,req.params.communityId);const p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT b.*,CASE WHEN e.Eligible=1 THEN 1 ELSE 0 END IsEligible,CASE WHEN fr.UserId IS NOT NULL THEN 1 ELSE 0 END HasVoted,(SELECT COUNT(*) FROM FormalBallotEligibility x WHERE x.BallotId=b.Id AND x.Eligible=1) EligibleCount,(SELECT COUNT(*) FROM FormalBallotReceipts x WHERE x.BallotId=b.Id) VoteCount FROM FormalBallots b LEFT JOIN FormalBallotEligibility e ON e.BallotId=b.Id AND e.UserId=@u LEFT JOIN FormalBallotReceipts fr ON fr.BallotId=b.Id AND fr.UserId=@u WHERE b.CommunityId=@c ORDER BY b.OpensAt DESC`);res.json(r.recordset);}));
advancedRouter.post('/communities/:communityId/formal-ballots',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'FORMAL_VOTE_MANAGE');const d=z.object({proposalId:z.string().uuid().optional(),title:z.string().min(2).max(250),description:z.string().optional(),options:z.array(z.string().min(1).max(500)).min(2).max(20),isAnonymous:z.boolean().default(true),quorumPercent:z.number().min(0).max(100).default(50),opensAt:z.coerce.date(),closesAt:z.coerce.date()}).parse(req.body);if(d.closesAt<=d.opensAt)throw new AppError(400,'Voting deadline must be after opening time');const p=await getPool();const tx=new sql.Transaction(p);await tx.begin();try{const b=(await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('p',sql.UniqueIdentifier,d.proposalId??null).input('u',sql.UniqueIdentifier,req.user!.id).input('t',sql.NVarChar(250),d.title).input('d',sql.NVarChar(sql.MAX),d.description??null).input('a',sql.Bit,d.isAnonymous).input('q',sql.Decimal(5,2),d.quorumPercent).input('o',sql.DateTime2,d.opensAt).input('cl',sql.DateTime2,d.closesAt).query(`INSERT INTO FormalBallots(CommunityId,ProposalId,CreatedBy,Title,Description,IsAnonymous,QuorumPercent,OpensAt,ClosesAt) OUTPUT INSERTED.* VALUES(@c,@p,@u,@t,@d,@a,@q,@o,@cl)`)).recordset[0];for(let i=0;i<d.options.length;i++)await new sql.Request(tx).input('b',sql.UniqueIdentifier,b.Id).input('l',sql.NVarChar(500),d.options[i]).input('s',sql.Int,i).query(`INSERT INTO FormalBallotOptions(BallotId,Label,SortOrder) VALUES(@b,@l,@s)`);await new sql.Request(tx).input('b',sql.UniqueIdentifier,b.Id).input('c',sql.UniqueIdentifier,req.params.communityId).query(`INSERT INTO FormalBallotEligibility(BallotId,UserId,Eligible,Reason) SELECT @b,UserId,1,'Active member at ballot creation' FROM CommunityMembers WHERE CommunityId=@c AND Status='ACTIVE'`);await tx.commit();res.status(201).json(b);}catch(e){await tx.rollback();throw e;}}));
advancedRouter.get('/formal-ballots/:ballotId',asyncHandler(async(req,res)=>{const p=await getPool();const br=await p.request().input('b',sql.UniqueIdentifier,req.params.ballotId).query(`SELECT * FROM FormalBallots WHERE Id=@b`);const b=br.recordset[0];if(!b)throw new AppError(404,'Ballot not found');await member(req.user!.id,b.CommunityId);const opts=await p.request().input('b',sql.UniqueIdentifier,req.params.ballotId).query(`SELECT o.Id,o.Label,o.SortOrder,CASE WHEN SYSUTCDATETIME()>b.ClosesAt OR b.Status='FINAL' THEN (SELECT COUNT(*) FROM FormalBallotVotes v WHERE v.OptionId=o.Id) ELSE NULL END VoteCount FROM FormalBallotOptions o JOIN FormalBallots b ON b.Id=o.BallotId WHERE o.BallotId=@b ORDER BY o.SortOrder`);const e=await p.request().input('b',sql.UniqueIdentifier,req.params.ballotId).input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT e.Eligible,CASE WHEN r.UserId IS NULL THEN 0 ELSE 1 END HasVoted FROM FormalBallotEligibility e LEFT JOIN FormalBallotReceipts r ON r.BallotId=e.BallotId AND r.UserId=e.UserId WHERE e.BallotId=@b AND e.UserId=@u`);res.json({...b,options:opts.recordset,...(e.recordset[0]??{Eligible:false,HasVoted:false})});}));
advancedRouter.post('/formal-ballots/:ballotId/vote',asyncHandler(async(req,res)=>{const {optionId}=z.object({optionId:z.string().uuid()}).parse(req.body);const p=await getPool();const tx=new sql.Transaction(p);await tx.begin();try{const br=await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).query(`SELECT * FROM FormalBallots WITH(UPDLOCK,HOLDLOCK) WHERE Id=@b`);const b=br.recordset[0];if(!b)throw new AppError(404,'Ballot not found');await member(req.user!.id,b.CommunityId);if(!['SCHEDULED','OPEN'].includes(b.Status)||b.FinalizedAt||new Date()<new Date(b.OpensAt)||new Date()>=new Date(b.ClosesAt))throw new AppError(409,'Ballot is not open');const er=await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT Eligible FROM FormalBallotEligibility WHERE BallotId=@b AND UserId=@u`);if(!er.recordset[0]?.Eligible)throw new AppError(403,'You are not eligible to vote');const option=(await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).input('o',sql.UniqueIdentifier,optionId).query('SELECT Id FROM FormalBallotOptions WITH(UPDLOCK,HOLDLOCK) WHERE Id=@o AND BallotId=@b')).recordset[0];if(!option)throw new AppError(400,'Option does not belong to this ballot');const receipt=crypto.createHash('sha256').update(`${req.params.ballotId}:${req.user!.id}:${crypto.randomUUID()}`).digest('hex');await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).input('u',sql.UniqueIdentifier,req.user!.id).input('r',sql.NVarChar(128),receipt).query(`IF EXISTS(SELECT 1 FROM FormalBallotReceipts WHERE BallotId=@b AND UserId=@u) THROW 51000,'Member has already voted',1; INSERT INTO FormalBallotReceipts(BallotId,UserId,ReceiptHash) VALUES(@b,@u,@r)`);const voter=b.IsAnonymous?null:req.user!.id;await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).input('o',sql.UniqueIdentifier,optionId).input('u',sql.UniqueIdentifier,voter).input('h',sql.NVarChar(128),b.IsAnonymous?receipt:null).query(`INSERT INTO FormalBallotVotes(BallotId,OptionId,VoterUserId,VoterTokenHash) VALUES(@b,@o,@u,@h)`);await tx.commit();res.json({success:true,receipt});}catch(e:any){await tx.rollback();if(String(e?.message).includes('already voted'))throw new AppError(409,'One member, one vote: vote already recorded');throw e;}}));
advancedRouter.post('/formal-ballots/:ballotId/finalize',asyncHandler(async(req,res)=>{const p=await getPool();const tx=new sql.Transaction(p);await tx.begin();try{const br=await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).query(`SELECT * FROM FormalBallots WITH(UPDLOCK,HOLDLOCK) WHERE Id=@b`);const b=br.recordset[0];if(!b)throw new AppError(404,'Ballot not found');await requirePermission(req.user!.id,b.CommunityId,'FORMAL_VOTE_MANAGE');if(!['SCHEDULED','OPEN','CLOSED'].includes(b.Status)||b.FinalizedAt)throw new AppError(409,'Ballot cannot be finalized in its current state');if(new Date()<new Date(b.ClosesAt))throw new AppError(409,'Ballot has not closed');const rr=await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).query(`SELECT (SELECT COUNT(*) FROM FormalBallotEligibility WHERE BallotId=@b AND Eligible=1) EligibleCount,(SELECT COUNT(*) FROM FormalBallotReceipts WHERE BallotId=@b) VoteCount`);const {EligibleCount,VoteCount}=rr.recordset[0];const turnout=EligibleCount?VoteCount/EligibleCount*100:0;const options=await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).query(`SELECT o.Id,o.Label,COUNT(v.Id) VoteCount FROM FormalBallotOptions o LEFT JOIN FormalBallotVotes v ON v.OptionId=o.Id AND v.BallotId=o.BallotId WHERE o.BallotId=@b GROUP BY o.Id,o.Label ORDER BY VoteCount DESC`);const quorumMet=turnout>=Number(b.QuorumPercent);const result=JSON.stringify({eligible:EligibleCount,votes:VoteCount,turnoutPercent:Number(turnout.toFixed(2)),quorumPercent:Number(b.QuorumPercent),quorumMet,options:options.recordset});await new sql.Request(tx).input('b',sql.UniqueIdentifier,req.params.ballotId).input('r',sql.NVarChar(sql.MAX),result).query(`UPDATE FormalBallots SET Status='FINAL',FinalResult=@r,FinalizedAt=SYSUTCDATETIME() WHERE Id=@b`);await new sql.Request(tx).input('c',sql.UniqueIdentifier,b.CommunityId).input('u',sql.UniqueIdentifier,req.user!.id).input('b',sql.UniqueIdentifier,b.Id).input('r',sql.NVarChar(sql.MAX),result).query(`INSERT INTO AuditLogs(CommunityId,UserId,Action,EntityType,EntityId,Details) VALUES(@c,@u,'BALLOT_FINALIZED','FormalBallot',@b,@r)`);await tx.commit();res.json(JSON.parse(result));}catch(e){await tx.rollback();throw e;}}));

// Finance member view and admin ledger
advancedRouter.use(levyRouter);
advancedRouter.get('/communities/:communityId/finance/summary',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'FINANCE_MANAGE');const p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT COALESCE(SUM(CASE WHEN TransactionType IN ('DUES','DONATION','FUNDRAISING','EVENT_PAYMENT','INCOME') THEN Amount ELSE 0 END),0) Income,COALESCE(SUM(CASE WHEN TransactionType='EXPENSE' THEN Amount ELSE 0 END),0) Expenses,COALESCE(SUM(CASE WHEN TransactionType IN ('DUES','DONATION','FUNDRAISING','EVENT_PAYMENT','INCOME') THEN Amount WHEN TransactionType='EXPENSE' THEN -Amount ELSE 0 END),0) Balance FROM FinanceTransactions WHERE CommunityId=@c; SELECT COUNT(*) OutstandingMembers,COALESCE(SUM(AmountDue-AmountPaid),0) OutstandingAmount FROM MemberDuesLedger WHERE CommunityId=@c AND AmountPaid<AmountDue`);const sets=r.recordsets as any[];res.json({totals:sets[0][0],dues:sets[1][0]});}));
advancedRouter.get('/communities/:communityId/finance/levies',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'FINANCE_MANAGE');const period=req.query.period==='past'?'past':'current';const p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('period',sql.NVarChar(10),period).query(`SELECT p.*,(SELECT COUNT(*) FROM MemberDuesLedger l WHERE l.PlanId=p.Id) AssignedCount,(SELECT COUNT(*) FROM MemberDuesLedger l WHERE l.PlanId=p.Id AND l.Status='PAID') PaidCount,(SELECT COUNT(*) FROM LevyPaymentSubmissions s JOIN MemberDuesLedger l ON l.Id=s.LedgerId WHERE l.PlanId=p.Id AND s.Status='PENDING') PendingCount FROM MemberDuesPlans p WHERE p.CommunityId=@c AND ((@period='current' AND p.IsActive=1 AND (p.DueDate IS NULL OR p.DueDate>=CAST(SYSUTCDATETIME() AS date))) OR (@period='past' AND (p.IsActive=0 OR p.DueDate<CAST(SYSUTCDATETIME() AS date)))) ORDER BY p.DueDate DESC,p.CreatedAt DESC`);res.json(r.recordset);}));
advancedRouter.get('/communities/:communityId/finance/levies/:planId',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'FINANCE_MANAGE');const p=await getPool();const plan=(await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('id',sql.UniqueIdentifier,req.params.planId).query(`SELECT * FROM MemberDuesPlans WHERE Id=@id AND CommunityId=@c`)).recordset[0];if(!plan)throw new AppError(404,'Levy not found');const rows=await p.request().input('id',sql.UniqueIdentifier,req.params.planId).query(`SELECT l.*,u.FirstName,u.LastName,u.Email,u.ProfileImage,cm.Status MembershipStatus,s.Id SubmissionId,s.Status SubmissionStatus,s.Reference,s.EvidenceUrl,s.Note,s.SubmittedAt FROM MemberDuesLedger l JOIN Users u ON u.Id=l.UserId LEFT JOIN CommunityMembers cm ON cm.CommunityId=l.CommunityId AND cm.UserId=l.UserId OUTER APPLY(SELECT TOP 1 * FROM LevyPaymentSubmissions x WHERE x.LedgerId=l.Id ORDER BY x.SubmittedAt DESC)s WHERE l.PlanId=@id ORDER BY u.FirstName,u.LastName`);res.json({plan,members:rows.recordset});}));
advancedRouter.patch('/communities/:communityId/finance/payment-submissions/:submissionId',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'FINANCE_MANAGE');const d=z.object({action:z.enum(['APPROVE','REJECT']),reviewNote:z.string().max(2000).optional()}).parse(req.body);const p=await getPool();const tx=new sql.Transaction(p);await tx.begin(sql.ISOLATION_LEVEL.SERIALIZABLE);try{const s=(await new sql.Request(tx).input('id',sql.UniqueIdentifier,req.params.submissionId).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT s.*,p.Name,p.CurrencyCode,l.AmountDue,l.AmountPaid FROM LevyPaymentSubmissions s WITH(UPDLOCK,HOLDLOCK) JOIN MemberDuesLedger l WITH(UPDLOCK,HOLDLOCK) ON l.Id=s.LedgerId JOIN MemberDuesPlans p ON p.Id=l.PlanId WHERE s.Id=@id AND s.CommunityId=@c AND s.Status='PENDING'`)).recordset[0];if(!s)throw new AppError(404,'Pending payment not found');if(d.action==='APPROVE'&&Number(s.Amount)>Number(s.AmountDue)-Number(s.AmountPaid))throw new AppError(409,'Payment exceeds the remaining balance. Review the ledger before approval');await new sql.Request(tx).input('id',sql.UniqueIdentifier,s.Id).input('u',sql.UniqueIdentifier,req.user!.id).input('status',sql.NVarChar(20),d.action==='APPROVE'?'APPROVED':'REJECTED').input('note',sql.NVarChar(2000),d.reviewNote??null).query(`UPDATE LevyPaymentSubmissions SET Status=@status,ReviewedBy=@u,ReviewedAt=SYSUTCDATETIME(),ReviewNote=@note WHERE Id=@id`);if(d.action==='APPROVE'){await new sql.Request(tx).input('id',sql.UniqueIdentifier,s.LedgerId).input('a',sql.Decimal(18,2),s.Amount).query(`UPDATE MemberDuesLedger SET AmountPaid=CASE WHEN AmountPaid+@a>AmountDue THEN AmountDue ELSE AmountPaid+@a END,Status=CASE WHEN AmountPaid+@a>=AmountDue THEN 'PAID' ELSE 'PARTIAL' END,UpdatedAt=SYSUTCDATETIME() WHERE Id=@id`);await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('uid',sql.UniqueIdentifier,s.UserId).input('desc',sql.NVarChar(500),s.Name).input('a',sql.Decimal(18,2),s.Amount).input('cc',sql.Char(3),s.CurrencyCode).input('ref',sql.NVarChar(120),s.Reference).input('u',sql.UniqueIdentifier,req.user!.id).query(`INSERT INTO FinanceTransactions(CommunityId,UserId,TransactionType,Description,Amount,CurrencyCode,Reference,CreatedBy) VALUES(@c,@uid,'DUES',@desc,@a,@cc,@ref,@u)`)}await tx.commit();res.json({success:true,status:d.action});}catch(e){await tx.rollback();throw e;}}));
advancedRouter.post('/communities/:communityId/finance/transactions',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'FINANCE_MANAGE');const d=z.object({userId:z.string().uuid().optional(),transactionType:z.enum(['DUES','DONATION','FUNDRAISING','EVENT_PAYMENT','INCOME','EXPENSE']),category:z.string().max(120).optional(),description:z.string().min(2).max(500),amount:z.number().positive(),currencyCode:z.string().length(3).default('GBP'),reference:z.string().max(120).optional(),planId:z.string().uuid().optional()}).parse(req.body);const p=await getPool();const tx=new sql.Transaction(p);await tx.begin();try{const r=(await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('uid',sql.UniqueIdentifier,d.userId??null).input('tt',sql.NVarChar(40),d.transactionType).input('cat',sql.NVarChar(120),d.category??null).input('desc',sql.NVarChar(500),d.description).input('a',sql.Decimal(18,2),d.amount).input('cc',sql.Char(3),d.currencyCode.toUpperCase()).input('ref',sql.NVarChar(120),d.reference??null).input('u',sql.UniqueIdentifier,req.user!.id).query(`INSERT INTO FinanceTransactions(CommunityId,UserId,TransactionType,Category,Description,Amount,CurrencyCode,Reference,CreatedBy) OUTPUT INSERTED.* VALUES(@c,@uid,@tt,@cat,@desc,@a,@cc,@ref,@u)`)).recordset[0];if(d.transactionType==='DUES'&&d.userId&&d.planId)await new sql.Request(tx).input('p',sql.UniqueIdentifier,d.planId).input('u',sql.UniqueIdentifier,d.userId).input('a',sql.Decimal(18,2),d.amount).query(`UPDATE MemberDuesLedger SET AmountPaid=AmountPaid+@a,Status=CASE WHEN AmountPaid+@a>=AmountDue THEN 'PAID' ELSE 'PARTIAL' END,UpdatedAt=SYSUTCDATETIME() WHERE PlanId=@p AND UserId=@u`);await tx.commit();res.status(201).json(r);}catch(e){await tx.rollback();throw e;}}));

// Knowledge/document centre with version history
advancedRouter.get('/communities/:communityId/documents',asyncHandler(async(req,res)=>{await member(req.user!.id,req.params.communityId);const q=String(req.query.q??'').trim(),p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('u',sql.UniqueIdentifier,req.user!.id).input('q',sql.NVarChar(500),`%${q.replace(/[%_]/g,'')}%`).query(`SELECT d.Id,d.CommunityId,d.Category,d.Title,d.Summary,d.Visibility,d.CurrentVersion,d.CreatedAt,d.UpdatedAt,attachment.OriginalName FileName,attachment.MimeType,attachment.SizeBytes,versionRow.CreatedAt UploadedAt,u.FirstName UploaderFirstName,u.LastName UploaderLastName FROM KnowledgeDocuments d LEFT JOIN KnowledgeDocumentVersions versionRow ON versionRow.DocumentId=d.Id AND versionRow.VersionNumber=d.CurrentVersion LEFT JOIN StoredObjects attachment ON attachment.Id=versionRow.StoredObjectId AND attachment.UploadState='AVAILABLE' AND attachment.DeletedAt IS NULL LEFT JOIN Users u ON u.Id=versionRow.UploadedBy WHERE d.CommunityId=@c AND ${documentVisibility} AND (@q='%%' OR d.Title LIKE @q OR d.Summary LIKE @q OR d.Category LIKE @q OR attachment.OriginalName LIKE @q) ORDER BY d.UpdatedAt DESC,d.Id`);res.json(r.recordset);}));
advancedRouter.post('/communities/:communityId/documents',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'DOCUMENT_MANAGE');const d=z.object({category:z.enum(documentCategories),title:z.string().min(2).max(250),summary:z.string().max(2000).optional(),visibility:z.enum(['MEMBERS','ADMINS']).default('MEMBERS'),storedObjectId:z.string().uuid(),changeNotes:z.string().max(1000).optional()}).strict().parse(req.body),p=await getPool();let storageKey:string|undefined;const tx=new sql.Transaction(p);await tx.begin();try{const object=(await new sql.Request(tx).input('id',sql.UniqueIdentifier,d.storedObjectId).input('u',sql.UniqueIdentifier,req.user!.id).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT StorageKey FROM StoredObjects WITH(UPDLOCK,HOLDLOCK) WHERE Id=@id AND UploadedBy=@u AND CommunityId=@c AND UploadState='AVAILABLE' AND IsPrivate=1 AND DeletedAt IS NULL AND NOT EXISTS(SELECT 1 FROM KnowledgeDocumentVersions WHERE StoredObjectId=@id)`)).recordset[0];if(!object)throw new AppError(400,'Uploaded object is unavailable or does not belong to this community');storageKey=object.StorageKey;const doc=(await new sql.Request(tx).input('c',sql.UniqueIdentifier,req.params.communityId).input('cat',sql.NVarChar(80),d.category).input('t',sql.NVarChar(250),d.title).input('s',sql.NVarChar(2000),d.summary??null).input('v',sql.NVarChar(30),d.visibility).input('u',sql.UniqueIdentifier,req.user!.id).query(`INSERT INTO KnowledgeDocuments(CommunityId,Category,Title,Summary,Visibility,CreatedBy) OUTPUT INSERTED.* VALUES(@c,@cat,@t,@s,@v,@u)`)).recordset[0];await new sql.Request(tx).input('d',sql.UniqueIdentifier,doc.Id).input('object',sql.UniqueIdentifier,d.storedObjectId).input('n',sql.NVarChar(1000),d.changeNotes??'Initial upload').input('u',sql.UniqueIdentifier,req.user!.id).query(`INSERT INTO KnowledgeDocumentVersions(DocumentId,VersionNumber,StoredObjectId,ChangeNotes,UploadedBy) VALUES(@d,1,@object,@n,@u)`);await tx.commit();res.status(201).json(doc)}catch(error){await tx.rollback();if(storageKey){await deleteObject(storageKey).catch(()=>{});await p.request().input('id',sql.UniqueIdentifier,d.storedObjectId).query(`UPDATE StoredObjects SET UploadState='DELETED',DeletedAt=SYSUTCDATETIME() WHERE Id=@id`).catch(()=>{})}throw error}}));
advancedRouter.post('/documents/:documentId/versions',asyncHandler(async(req,res)=>{const d=z.object({storedObjectId:z.string().uuid(),changeNotes:z.string().min(2).max(1000)}).strict().parse(req.body),p=await getPool(),doc=await requireDocumentView(req.user!.id,req.params.documentId);await requirePermission(req.user!.id,doc.CommunityId,'DOCUMENT_MANAGE');const next=doc.CurrentVersion+1,tx=new sql.Transaction(p);await tx.begin();try{const object=(await new sql.Request(tx).input('id',sql.UniqueIdentifier,d.storedObjectId).input('u',sql.UniqueIdentifier,req.user!.id).input('c',sql.UniqueIdentifier,doc.CommunityId).query(`SELECT Id FROM StoredObjects WITH(UPDLOCK,HOLDLOCK) WHERE Id=@id AND UploadedBy=@u AND CommunityId=@c AND UploadState='AVAILABLE' AND IsPrivate=1 AND DeletedAt IS NULL AND NOT EXISTS(SELECT 1 FROM KnowledgeDocumentVersions WHERE StoredObjectId=@id)`)).recordset[0];if(!object)throw new AppError(400,'Uploaded object is unavailable');await new sql.Request(tx).input('d',sql.UniqueIdentifier,req.params.documentId).input('v',sql.Int,next).input('object',sql.UniqueIdentifier,d.storedObjectId).input('n',sql.NVarChar(1000),d.changeNotes).input('u',sql.UniqueIdentifier,req.user!.id).query(`INSERT INTO KnowledgeDocumentVersions(DocumentId,VersionNumber,StoredObjectId,ChangeNotes,UploadedBy) VALUES(@d,@v,@object,@n,@u)`);await new sql.Request(tx).input('d',sql.UniqueIdentifier,req.params.documentId).input('v',sql.Int,next).query(`UPDATE KnowledgeDocuments SET CurrentVersion=@v,UpdatedAt=SYSUTCDATETIME() WHERE Id=@d`);await tx.commit();res.status(201).json({success:true,version:next})}catch(error){await tx.rollback();throw error}}));
advancedRouter.get('/documents/:documentId',asyncHandler(async(req,res)=>{const doc=await requireDocumentView(req.user!.id,req.params.documentId),p=await getPool(),r=await p.request().input('d',sql.UniqueIdentifier,doc.Id).query(`SELECT d.Id,d.CommunityId,d.Category,d.Title,d.Summary,d.Visibility,d.CurrentVersion,d.CreatedAt,d.UpdatedAt,attachment.OriginalName FileName,attachment.MimeType,attachment.SizeBytes,versionRow.CreatedAt UploadedAt,u.FirstName UploaderFirstName,u.LastName UploaderLastName FROM KnowledgeDocuments d LEFT JOIN KnowledgeDocumentVersions versionRow ON versionRow.DocumentId=d.Id AND versionRow.VersionNumber=d.CurrentVersion LEFT JOIN StoredObjects attachment ON attachment.Id=versionRow.StoredObjectId AND attachment.UploadState='AVAILABLE' AND attachment.DeletedAt IS NULL LEFT JOIN Users u ON u.Id=versionRow.UploadedBy WHERE d.Id=@d`);res.json(r.recordset[0])}));
advancedRouter.get('/documents/:documentId/history',asyncHandler(async(req,res)=>{await requireDocumentView(req.user!.id,req.params.documentId);const p=await getPool(),r=await p.request().input('d',sql.UniqueIdentifier,req.params.documentId).query(`SELECT versionRow.Id,versionRow.VersionNumber,versionRow.ChangeNotes,versionRow.CreatedAt UploadedAt,attachment.OriginalName FileName,attachment.MimeType,attachment.SizeBytes,u.FirstName UploaderFirstName,u.LastName UploaderLastName FROM KnowledgeDocumentVersions versionRow LEFT JOIN StoredObjects attachment ON attachment.Id=versionRow.StoredObjectId AND attachment.UploadState='AVAILABLE' AND attachment.DeletedAt IS NULL JOIN Users u ON u.Id=versionRow.UploadedBy WHERE versionRow.DocumentId=@d ORDER BY versionRow.VersionNumber DESC,versionRow.Id`);res.json(r.recordset)}));
advancedRouter.post('/documents/:documentId/download-url',asyncHandler(async(req,res)=>{const doc=await requireDocumentView(req.user!.id,req.params.documentId),p=await getPool(),attachment=(await p.request().input('d',sql.UniqueIdentifier,doc.Id).query(`SELECT attachment.Id FROM KnowledgeDocumentVersions versionRow JOIN StoredObjects attachment ON attachment.Id=versionRow.StoredObjectId AND attachment.UploadState='AVAILABLE' AND attachment.DeletedAt IS NULL WHERE versionRow.DocumentId=@d AND versionRow.VersionNumber=(SELECT CurrentVersion FROM KnowledgeDocuments WHERE Id=@d)`)).recordset[0];if(!attachment)throw new AppError(404,'Document attachment not found');const token=crypto.randomBytes(32).toString('base64url');await getRedis().set(`document-download:${token}`,JSON.stringify({userId:req.user!.id,documentId:doc.Id,storedObjectId:attachment.Id}),'EX',300);res.json({url:`${env.PUBLIC_BASE_URL.replace(/\/$/,'')}/api/v1/media/document-download/${token}`,expiresInSeconds:300})}));
advancedRouter.post('/documents/:documentId/share-link',asyncHandler(async(req,res)=>{const doc=await requireDocumentView(req.user!.id,req.params.documentId);if(doc.Visibility==='ADMINS')throw new AppError(404,'Document not found');res.json({path:`/community/${doc.CommunityId}/documents?documentId=${doc.Id}`})}));

