advancedRouter.put('/me/notification-preferences',asyncHandler(async(req,res)=>{const d=z.object({emergencyAlerts:z.enum(['ALWAYS']).default('ALWAYS'),directMessages:z.enum(['ON','OFF']).default('ON'),mentions:z.enum(['ON','OFF']).default('ON'),communityPosts:z.enum(['ON','OFF']).default('ON'),polls:z.enum(['ON','OFF']).default('ON'),events:z.enum(['ON','OFF']).default('ON'),marketplace:z.enum(['ON','OFF']).default('OFF'),businessPromotions:z.enum(['ON','OFF']).default('OFF'),quietHoursEnabled:z.boolean().default(false),quietStart:z.string().regex(/^\d\d:\d\d$/).optional(),quietEnd:z.string().regex(/^\d\d:\d\d$/).optional(),notificationPreviewsEnabled:z.boolean().default(false),timeZone:z.string().min(1).max(100)}).parse(req.body);try{new Intl.DateTimeFormat('en',{timeZone:d.timeZone}).format()}catch{throw new AppError(400,'Invalid timezone')};const p=await getPool();const tx=new sql.Transaction(p);await tx.begin();try{await new sql.Request(tx).input('u',sql.UniqueIdentifier,req.user!.id).input('dm',sql.NVarChar(20),d.directMessages).input('m',sql.NVarChar(20),d.mentions).input('cp',sql.NVarChar(20),d.communityPosts).input('po',sql.NVarChar(20),d.polls).input('e',sql.NVarChar(20),d.events).input('mp',sql.NVarChar(20),d.marketplace).input('bp',sql.NVarChar(20),d.businessPromotions).input('qh',sql.Bit,d.quietHoursEnabled).input('qs',sql.VarChar(5),d.quietStart??null).input('qe',sql.VarChar(5),d.quietEnd??null).query(`MERGE NotificationPreferences t USING(SELECT @u UserId)s ON t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET DirectMessages=@dm,Mentions=@m,CommunityPosts=@cp,Polls=@po,Events=@e,Marketplace=@mp,BusinessPromotions=@bp,QuietHoursEnabled=@qh,QuietStart=TRY_CONVERT(time,@qs),QuietEnd=TRY_CONVERT(time,@qe),UpdatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(UserId,DirectMessages,Mentions,CommunityPosts,Polls,Events,Marketplace,BusinessPromotions,QuietHoursEnabled,QuietStart,QuietEnd) VALUES(@u,@dm,@m,@cp,@po,@e,@mp,@bp,@qh,TRY_CONVERT(time,@qs),TRY_CONVERT(time,@qe));`);await new sql.Request(tx).input('u',sql.UniqueIdentifier,req.user!.id).input('preview',sql.Bit,d.notificationPreviewsEnabled).input('tz',sql.NVarChar(100),d.timeZone).query(`MERGE UserAppPreferences t USING(SELECT @u UserId)s ON t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET NotificationPreviewsEnabled=@preview,TimeZone=@tz,UpdatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(UserId,NotificationPreviewsEnabled,TimeZone) VALUES(@u,@preview,@tz);`);await tx.commit();res.json({success:true})}catch(error){await tx.rollback();throw error}}));
advancedRouter.put('/me/privacy-preferences',asyncHandler(async(req,res)=>{const d=z.object({phoneVisibility:z.enum(['NOBODY','ADMINS','MEMBERS']),emailVisibility:z.enum(['NOBODY','ADMINS','MEMBERS']),whoCanMessage:z.enum(['NOBODY','ADMINS','MEMBERS']),whoCanAddToGroups:z.enum(['NOBODY','ADMINS','MEMBERS']),showOnlineStatus:z.boolean(),showProfilePhoto:z.boolean(),allowCommunityDiscovery:z.boolean()}).parse(req.body);const p=await getPool();await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('pv',sql.NVarChar(20),d.phoneVisibility).input('ev',sql.NVarChar(20),d.emailVisibility).input('wm',sql.NVarChar(20),d.whoCanMessage).input('wg',sql.NVarChar(20),d.whoCanAddToGroups).input('os',sql.Bit,d.showOnlineStatus).input('pp',sql.Bit,d.showProfilePhoto).input('cd',sql.Bit,d.allowCommunityDiscovery).query(`MERGE PrivacyPreferences t USING(SELECT @u UserId)s ON t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET PhoneVisibility=@pv,EmailVisibility=@ev,WhoCanMessage=@wm,WhoCanAddToGroups=@wg,ShowOnlineStatus=@os,ShowProfilePhoto=@pp,AllowCommunityDiscovery=@cd,UpdatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(UserId,PhoneVisibility,EmailVisibility,WhoCanMessage,WhoCanAddToGroups,ShowOnlineStatus,ShowProfilePhoto,AllowCommunityDiscovery) VALUES(@u,@pv,@ev,@wm,@wg,@os,@pp,@cd);`);res.json({success:true});}));
advancedRouter.put('/me/app-preferences',asyncHandler(async(req,res)=>{const d=z.object({dataSaverEnabled:z.boolean(),offlineCacheEnabled:z.boolean(),autoDownloadImages:z.boolean(),autoDownloadVideos:z.boolean()}).parse(req.body);const p=await getPool();await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('ds',sql.Bit,d.dataSaverEnabled).input('oc',sql.Bit,d.offlineCacheEnabled).input('ai',sql.Bit,d.autoDownloadImages).input('av',sql.Bit,d.autoDownloadVideos).query(`MERGE UserAppPreferences t USING(SELECT @u UserId)s ON t.UserId=s.UserId WHEN MATCHED THEN UPDATE SET DataSaverEnabled=@ds,OfflineCacheEnabled=@oc,AutoDownloadImages=@ai,AutoDownloadVideos=@av,UpdatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(UserId,DataSaverEnabled,OfflineCacheEnabled,AutoDownloadImages,AutoDownloadVideos) VALUES(@u,@ds,@oc,@ai,@av);`);res.json({success:true});}));
advancedRouter.get('/me/blocked-users',asyncHandler(async(req,res)=>{const p=await getPool();const result=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT u.Id,u.FirstName,u.LastName,u.ProfileImage FROM BlockedUsers b JOIN Users u ON u.Id=b.BlockedUserId WHERE b.UserId=@u ORDER BY u.FirstName,u.LastName`);res.json(result.recordset);}));
