// Personalised home and smart summaries
advancedRouter.get('/me/home',asyncHandler(async(req,res)=>{const p=await getPool();const communities=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT c.Id,c.Name,c.LogoUrl,c.BannerUrl,c.City,c.Country,cm.JoinedAt,STRING_AGG(r.Name,', ') Roles,(SELECT COUNT(*) FROM CommunityMembers members WHERE members.CommunityId=c.Id AND members.Status='ACTIVE') MemberCount,(SELECT COUNT(*) FROM CommunityPosts cp WHERE cp.CommunityId=c.Id AND cp.CreatedAt>DATEADD(day,-7,SYSUTCDATETIME()) AND cp.IsDeleted=0) NewPosts,(SELECT COUNT(*) FROM Messages m JOIN Conversations cv ON cv.Id=m.ConversationId WHERE cv.CommunityId=c.Id AND m.CreatedAt>DATEADD(day,-1,SYSUTCDATETIME())) RecentMessages FROM CommunityMembers cm JOIN Communities c ON c.Id=cm.CommunityId LEFT JOIN CommunityMemberRoles cmr ON cmr.CommunityMemberId=cm.Id LEFT JOIN Roles r ON r.Id=cmr.RoleId WHERE cm.UserId=@u AND cm.Status='ACTIVE' GROUP BY c.Id,c.Name,c.LogoUrl,c.BannerUrl,c.City,c.Country,cm.JoinedAt`);const alerts=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT TOP 5 a.* FROM EmergencyAlerts a JOIN CommunityMembers cm ON cm.CommunityId=a.CommunityId AND cm.UserId=@u WHERE cm.Status='ACTIVE' AND a.Active=1 ORDER BY a.CreatedAt DESC`);const upcoming=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT TOP 10 'MEETING' ItemType,m.Id,m.CommunityId,m.Title,m.StartDateTime DueAt FROM Meetings m JOIN CommunityMembers cm ON cm.CommunityId=m.CommunityId AND cm.UserId=@u WHERE cm.Status='ACTIVE' AND dbo.CanViewMeeting(m.Id,@u)=1 AND m.StartDateTime>=SYSUTCDATETIME() UNION ALL SELECT TOP 10 'EVENT',e.Id,e.CommunityId,e.Title,e.StartDateTime FROM CommunityEvents e JOIN CommunityMembers cm ON cm.CommunityId=e.CommunityId AND cm.UserId=@u WHERE cm.Status='ACTIVE' AND e.StartDateTime>=SYSUTCDATETIME() ORDER BY DueAt`);const tasks=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT TOP 10 * FROM GovernanceActions WHERE AssignedTo=@u AND Status<>'DONE' ORDER BY DueAt`);res.json({communities:communities.recordset,importantAlerts:alerts.recordset,upcoming:upcoming.recordset,tasks:tasks.recordset});}));
advancedRouter.get('/communities/:communityId/smart-summary',asyncHandler(async(req,res)=>{await member(req.user!.id,req.params.communityId);const p=await getPool();const since=new Date(Date.now()-7*86400000);const posts=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('s',sql.DateTime2,since).query(`SELECT TOP 10 Body,CreatedAt FROM CommunityPosts WHERE CommunityId=@c AND CreatedAt>=@s AND IsDeleted=0 ORDER BY CreatedAt DESC`);const meetings=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('c',sql.UniqueIdentifier,req.params.communityId).input('s',sql.DateTime2,since).query(`SELECT TOP 10 Title,StartDateTime FROM Meetings WHERE dbo.CanViewMeeting(Id,@u)=1 AND CommunityId=@c AND StartDateTime>=@s ORDER BY StartDateTime`);const issues=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('s',sql.DateTime2,since).query(`SELECT Status,COUNT(*) Count FROM CommunityIssues WHERE CommunityId=@c AND CreatedAt>=@s GROUP BY Status`);const ballots=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('s',sql.DateTime2,since).query(`SELECT TOP 10 Title,Status,ClosesAt FROM FormalBallots WHERE CommunityId=@c AND CreatedAt>=@s ORDER BY CreatedAt DESC`);const bullets:any[]=[];if(posts.recordset.length)bullets.push(`${posts.recordset.length} recent community posts were published.`);meetings.recordset.slice(0,2).forEach((x:any)=>bullets.push(`Meeting: ${x.Title} on ${new Date(x.StartDateTime).toLocaleDateString()}.`));issues.recordset.forEach((x:any)=>bullets.push(`${x.Count} issue report(s) are ${String(x.Status).toLowerCase().replace('_',' ')}.`));ballots.recordset.slice(0,2).forEach((x:any)=>bullets.push(`Formal vote: ${x.Title} is ${String(x.Status).toLowerCase()}.`));res.json({title:'While you were away',periodDays:7,bullets,generatedBy:'deterministic-summary'});}));

// Personal streams aggregate real activity from every community the caller belongs to.
advancedRouter.get('/me/activity',asyncHandler(async(req,res)=>{const p=await getPool();const r=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT TOP 100 cp.Id,cp.CommunityId,cp.CreatedBy,c.Name CommunityName,cp.Body,cp.PostType,cp.IsAnnouncement,cp.CreatedAt,u.FirstName,u.LastName,u.ProfileImage,(SELECT COUNT(*) FROM PostReactions pr WHERE pr.PostId=cp.Id) ReactionCount,(SELECT COUNT(*) FROM PostComments pc WHERE pc.PostId=cp.Id AND pc.IsDeleted=0) CommentCount FROM CommunityPosts cp JOIN Communities c ON c.Id=cp.CommunityId JOIN CommunityMembers cm ON cm.CommunityId=c.Id AND cm.UserId=@u AND cm.Status='ACTIVE' JOIN Users u ON u.Id=cp.CreatedBy WHERE cp.IsDeleted=0 ORDER BY cp.CreatedAt DESC`);res.json(r.recordset);}));
advancedRouter.get('/me/announcements',asyncHandler(async(req,res)=>{const p=await getPool();const r=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT a.*,c.Name CommunityName FROM Announcements a JOIN Communities c ON c.Id=a.CommunityId JOIN CommunityMembers cm ON cm.CommunityId=c.Id AND cm.UserId=@u AND cm.Status='ACTIVE' ORDER BY a.CreatedAt DESC`);res.json(r.recordset);}));
advancedRouter.get('/me/events',asyncHandler(async(req,res)=>{const p=await getPool();const r=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT 'EVENT' ItemType,e.Id,e.CommunityId,c.Name CommunityName,e.Title,e.Description,e.Location,e.StartDateTime DueAt FROM CommunityEvents e JOIN Communities c ON c.Id=e.CommunityId JOIN CommunityMembers cm ON cm.CommunityId=c.Id AND cm.UserId=@u AND cm.Status='ACTIVE' WHERE e.StartDateTime>=DATEADD(day,-1,SYSUTCDATETIME()) UNION ALL SELECT 'MEETING',m.Id,m.CommunityId,c.Name,m.Title,m.Description,m.Location,m.StartDateTime FROM Meetings m JOIN Communities c ON c.Id=m.CommunityId JOIN CommunityMembers cm ON cm.CommunityId=c.Id AND cm.UserId=@u AND cm.Status='ACTIVE' WHERE dbo.CanViewMeeting(m.Id,@u)=1 AND m.StartDateTime>=DATEADD(day,-1,SYSUTCDATETIME()) ORDER BY DueAt`);res.json(r.recordset);}));
advancedRouter.get('/me/notifications',asyncHandler(async(req,res)=>{const p=await getPool();const r=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`SELECT TOP 100 n.Id,n.NotificationId,n.NotificationType,n.Title,CASE WHEN (n.NotificationType IN('POST','COMMENT') AND NOT EXISTS(SELECT 1 FROM CommunityPosts cp WHERE cp.Id=COALESCE(TRY_CONVERT(uniqueidentifier,JSON_VALUE(n.NavigationData,'$.postId')),n.EntityId) AND cp.IsDeleted=0)) OR (n.NotificationType='CHAT_MESSAGE' AND NOT EXISTS(SELECT 1 FROM ConversationMembers x WHERE x.ConversationId=TRY_CONVERT(uniqueidentifier,JSON_VALUE(n.NavigationData,'$.conversationId')) AND x.UserId=@u AND x.IsActive=1)) THEN 'This content is no longer available.' ELSE n.Body END Body,n.CommunityId,c.Name CommunityName,n.EntityId,n.NavigationData,n.CreatedAt,n.ReadAt,n.DeliveryStatus,CAST(CASE WHEN n.ReadAt IS NULL THEN 0 ELSE 1 END AS bit) IsRead FROM UserNotifications n JOIN Communities c ON c.Id=n.CommunityId JOIN CommunityMembers cm ON cm.CommunityId=n.CommunityId AND cm.UserId=n.UserId AND cm.Status='ACTIVE' WHERE n.UserId=@u AND (JSON_VALUE(n.NavigationData,'$.requiresPermission') IS NULL OR EXISTS(SELECT 1 FROM CommunityMembers member JOIN CommunityMemberRoles mr ON mr.CommunityMemberId=member.Id JOIN RolePermissions rp ON rp.RoleId=mr.RoleId JOIN Permissions permission ON permission.Id=rp.PermissionId WHERE member.CommunityId=n.CommunityId AND member.UserId=@u AND member.Status='ACTIVE' AND permission.Code=JSON_VALUE(n.NavigationData,'$.requiresPermission'))) ORDER BY n.CreatedAt DESC`);res.json(r.recordset.map((item:any)=>({...item,NavigationData:item.NavigationData?JSON.parse(item.NavigationData):{}})));}));
advancedRouter.put('/me/notifications/read',asyncHandler(async(req,res)=>{const{notificationIds}=z.object({notificationIds:z.array(z.string().uuid()).min(1).max(100)}).parse(req.body);const p=await getPool();await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('ids',sql.NVarChar(sql.MAX),JSON.stringify(notificationIds)).query(`UPDATE n SET ReadAt=COALESCE(ReadAt,SYSUTCDATETIME()) FROM UserNotifications n JOIN OPENJSON(@ids) ids ON TRY_CONVERT(uniqueidentifier,ids.[value])=n.Id WHERE n.UserId=@u`);res.json({success:true});}));
advancedRouter.put('/me/notifications/read-all',asyncHandler(async(req,res)=>{const p=await getPool();await p.request().input('u',sql.UniqueIdentifier,req.user!.id).query(`UPDATE UserNotifications SET ReadAt=COALESCE(ReadAt,SYSUTCDATETIME()) WHERE UserId=@u AND ReadAt IS NULL`);res.json({success:true});}));

// Analytics and explainable community health score
advancedRouter.get('/communities/:communityId/analytics',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'ANALYTICS_VIEW');const p=await getPool();const c=req.params.communityId;const members=await p.request().input('c',sql.UniqueIdentifier,c).query(`SELECT COUNT(*) MemberCount,SUM(CASE WHEN JoinedAt>=DATEADD(day,-30,SYSUTCDATETIME()) THEN 1 ELSE 0 END) NewMembers30d FROM CommunityMembers WHERE CommunityId=@c AND Status='ACTIVE'`);const active=await p.request().input('c',sql.UniqueIdentifier,c).query(`SELECT COUNT(DISTINCT UserId) ActiveUsers FROM (SELECT CreatedBy UserId FROM CommunityPosts WHERE CommunityId=@c AND CreatedAt>=DATEADD(day,-30,SYSUTCDATETIME()) UNION SELECT SenderUserId FROM Messages m JOIN Conversations cv ON cv.Id=m.ConversationId WHERE cv.CommunityId=@c AND m.CreatedAt>=DATEADD(day,-30,SYSUTCDATETIME())) x`);const meetings=await p.request().input('c',sql.UniqueIdentifier,c).query(`SELECT COUNT(*) TotalResponses,SUM(CASE WHEN ma.Response='GOING' THEN 1 ELSE 0 END) Going FROM MeetingAttendees ma JOIN Meetings m ON m.Id=ma.MeetingId WHERE m.CommunityId=@c AND m.StartDateTime>=DATEADD(day,-90,SYSUTCDATETIME())`);const polls=await p.request().input('c',sql.UniqueIdentifier,c).query(`SELECT COUNT(DISTINCT pv.UserId) Voters,(SELECT COUNT(*) FROM CommunityMembers WHERE CommunityId=@c AND Status='ACTIVE') Members FROM PollVotes pv JOIN Polls p ON p.Id=pv.PollId WHERE p.CommunityId=@c AND pv.CreatedAt>=DATEADD(day,-90,SYSUTCDATETIME())`);const issues=await p.request().input('c',sql.UniqueIdentifier,c).query(`SELECT SUM(CASE WHEN Status<>'RESOLVED' THEN 1 ELSE 0 END) OpenIssues,SUM(CASE WHEN Status='RESOLVED' AND UpdatedAt>=DATEADD(day,-30,SYSUTCDATETIME()) THEN 1 ELSE 0 END) ResolvedIssues30d FROM CommunityIssues WHERE CommunityId=@c`);const content=await p.request().input('c',sql.UniqueIdentifier,c).query(`SELECT (SELECT COUNT(*) FROM CommunityPosts WHERE CommunityId=@c AND CreatedAt>=DATEADD(day,-30,SYSUTCDATETIME()) AND IsDeleted=0)+(SELECT COUNT(*) FROM Messages m JOIN Conversations cv ON cv.Id=m.ConversationId WHERE cv.CommunityId=@c AND m.CreatedAt>=DATEADD(day,-30,SYSUTCDATETIME())) PostMessageCount30d`);const mc=Number(members.recordset[0].MemberCount||0), mau=mc?Number(active.recordset[0].ActiveUsers||0)/mc*100:0, mr=Number(meetings.recordset[0].TotalResponses||0), rsvp=mr?Number(meetings.recordset[0].Going||0)/mr*100:0, part=Number(polls.recordset[0].Members||0)?Number(polls.recordset[0].Voters||0)/Number(polls.recordset[0].Members)*100:0, open=Number(issues.recordset[0].OpenIssues||0), resolved=Number(issues.recordset[0].ResolvedIssues30d||0), issueScore=(open+resolved)?resolved/(open+resolved)*100:100;const engagement=Math.min(100,mau),meetingScore=Math.min(100,rsvp),participation=Math.min(100,part),adminResponse=Math.max(50,Math.min(100,100-open*2)),overall=engagement*.25+meetingScore*.15+issueScore*.25+participation*.20+adminResponse*.15;const explanation='v1 formula: engagement 25% + meeting activity 15% + issue resolution 25% + participation 20% + admin response proxy 15%. Each component is capped at 100 and derived from observed community activity, not AI judgment.';res.json({members:{count:mc,new30d:Number(members.recordset[0].NewMembers30d||0)},monthlyActivePercent:+mau.toFixed(1),meetingRsvpPercent:+rsvp.toFixed(1),pollParticipationPercent:+part.toFixed(1),issues:{open,resolved30d:resolved},postMessageCount30d:Number(content.recordset[0].PostMessageCount30d||0),health:{engagement:+engagement.toFixed(1),meetingActivity:+meetingScore.toFixed(1),issueResolution:+issueScore.toFixed(1),participation:+participation.toFixed(1),adminResponse:+adminResponse.toFixed(1),overall:+overall.toFixed(1),formulaVersion:'v1',explanation}});}));

// Human-in-the-loop AI moderation queue. Detection may be supplied by a configured provider later; deletion is never automatic here.
advancedRouter.get('/communities/:communityId/moderation-queue',asyncHandler(async(req,res)=>{await requirePermission(req.user!.id,req.params.communityId,'MODERATION_REVIEW');const p=await getPool();const r=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT * FROM ModerationQueue WHERE CommunityId=@c ORDER BY CASE Status WHEN 'PENDING_REVIEW' THEN 0 ELSE 1 END,CreatedAt DESC`);res.json(r.recordset);}));
advancedRouter.post('/communities/:communityId/moderation-queue',asyncHandler(async(req,res)=>{const d=z.object({entityType:z.enum(['POST','COMMENT','MARKETPLACE']),entityId:z.string().uuid(),reasonCode:z.string().max(80),confidence:z.number().min(0).max(1).optional(),explanation:z.string().max(2000).optional()}).parse(req.body);res.status(201).json(await reportContent(req.user!.id,req.params.communityId,d));}));
advancedRouter.patch('/moderation-queue/:itemId/review',asyncHandler(async(req,res)=>{const d=z.object({decision:z.enum(['APPROVE','REMOVE']),notes:z.string().max(2000).optional()}).parse(req.body);res.json(await reviewContent(req.user!.id,req.params.itemId,d.decision,d.notes));}));

// Permission-aware assistant context endpoint. This intentionally returns only content the caller can already access.
advancedRouter.post('/communities/:communityId/assistant/context',asyncHandler(async(req,res)=>{await member(req.user!.id,req.params.communityId);const {question}=z.object({question:z.string().min(2).max(1000)}).parse(req.body);const p=await getPool();const q=`%${question.replace(/[%_]/g,'')}%`;const decisions=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).input('q',sql.NVarChar(1000),q).query(`SELECT TOP 8 Id,Title,DecisionText,DecisionDate FROM DecisionRegister WHERE CommunityId=@c AND (Title LIKE @q OR DecisionText LIKE @q OR SearchText LIKE @q) ORDER BY DecisionDate DESC`);const docs=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('c',sql.UniqueIdentifier,req.params.communityId).input('q',sql.NVarChar(1000),q).query(`SELECT TOP 8 d.Id,d.Title,d.Category,v.Body FROM KnowledgeDocuments d LEFT JOIN KnowledgeDocumentVersions v ON v.DocumentId=d.Id AND v.VersionNumber=d.CurrentVersion WHERE d.CommunityId=@c AND ${documentVisibility} AND (d.Title LIKE @q OR d.Summary LIKE @q OR v.Body LIKE @q) ORDER BY d.UpdatedAt DESC`);const announcements=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT TOP 8 Id,Title,Body,CreatedAt FROM Announcements WHERE CommunityId=@c ORDER BY CreatedAt DESC`);const meetings=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT TOP 8 Id,Title,StartDateTime,Location FROM Meetings WHERE dbo.CanViewMeeting(Id,@u)=1 AND CommunityId=@c AND StartDateTime>=DATEADD(day,-90,SYSUTCDATETIME()) ORDER BY StartDateTime DESC`);res.json({question,context:{decisions:decisions.recordset,documents:docs.recordset,announcements:announcements.recordset,meetings:meetings.recordset},note:'This endpoint supplies permission-filtered context. Connect your chosen AI model service in a server-side provider adapter; never send private database credentials or bypass community permissions.'});}));

// Optional AI provider adapter. Context is assembled server-side after permission checks.
advancedRouter.post('/communities/:communityId/assistant/ask',asyncHandler(async(req,res)=>{
  await member(req.user!.id,req.params.communityId);
  const {question,mode}=z.object({question:z.string().min(2).max(1000),mode:z.enum(['MEMBER','ADMIN']).default('MEMBER')}).parse(req.body);
  const p=await getPool();
  const decisions=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT TOP 12 Title,DecisionText,DecisionDate FROM DecisionRegister WHERE CommunityId=@c ORDER BY DecisionDate DESC`);
  const meetings=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT TOP 12 Title,StartDateTime,Location FROM Meetings WHERE dbo.CanViewMeeting(Id,@u)=1 AND CommunityId=@c ORDER BY StartDateTime DESC`);
  const announcements=await p.request().input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT TOP 12 Title,Body,CreatedAt FROM Announcements WHERE CommunityId=@c ORDER BY CreatedAt DESC`);
  const docs=await p.request().input('u',sql.UniqueIdentifier,req.user!.id).input('c',sql.UniqueIdentifier,req.params.communityId).query(`SELECT TOP 12 d.Title,d.Category,v.Body FROM KnowledgeDocuments d LEFT JOIN KnowledgeDocumentVersions v ON v.DocumentId=d.Id AND v.VersionNumber=d.CurrentVersion WHERE d.CommunityId=@c AND ${documentVisibility} ORDER BY d.UpdatedAt DESC`);
  const context={decisions:decisions.recordset,meetings:meetings.recordset,announcements:announcements.recordset,documents:docs.recordset};
  const { env } = await import('../config/env.js');
  if(!env.AI_SERVICE_URL){return res.json({answer:'AI provider is not configured yet. I can still show the authorised community context used to answer this question.',context,providerConfigured:false});}
  const rr=await fetch(env.AI_SERVICE_URL,{method:'POST',headers:{'content-type':'application/json',...(env.AI_SERVICE_API_KEY?{'authorization':`Bearer ${env.AI_SERVICE_API_KEY}`}:{})},body:JSON.stringify({question,mode,context,instructions:'Answer only from supplied context. Do not infer private information. If the answer is unavailable, say so.'})});
  if(!rr.ok)throw new AppError(502,'AI provider failed'); const data:any=await rr.json();
  res.json({answer:data.answer??data.output??String(data),providerConfigured:true});
}));

advancedRouter.get('/me/personal-activity',asyncHandler(async(req,res)=>{const q=z.object({kind:z.enum(['ALL','POST','COMMENT','REACTION','GROUP','MEETING','EVENT']).default('ALL'),cursor:z.string().max(500).optional()}).parse(req.query);res.json(await personalActivity(req.user!.id,q.kind,q.cursor));}));

advancedRouter.get('/me/recent-activity',asyncHandler(async(req,res)=>{const q=z.object({q:z.string().trim().max(200).default(''),cursor:z.string().max(500).optional()}).parse(req.query);res.set('Cache-Control','no-store').json(await recentActivity(req.user!.id,q.q,q.cursor));}));
